// Finds the hub device and its entities by their ORIGINAL ESPHome names, not by entity_id, so the cards work whatever
// the device name, area prefix or entity-id format in HA. ESPHome has no language-independent entity id (the HA
// unique_id contains the name), so NAMES lists every language of the packages (generated by tools/gen_names.py) and
// an entity matches by its name after the bus prefix ("<prefix> - <name>"), whatever prefix the user set.
// Without a hub the cards fall back to the Immergas Dominus integration (local TCP to the Dominus Wi-Fi module): its
// entities are matched by their key (the unique_id after the config entry id), so a reduced dashboard works with it too.
import { NAMES, Key } from "./names";
import { findPkg } from "./hubpkg";

export interface HubIndex {
  deviceId: string;
  lang: "pl" | "en";
  ids: Partial<Record<Key, string>>;
  /** "hub" = the ESPHome hub, "dominus" = the Immergas Dominus integration (fewer entities, no heat-pump data) */
  source: "hub" | "dominus";
  gas?: boolean;
  /** Dominus in the OpenTherm mode (VICTRIX ZEUS / AVIO …): only the OpenTherm Data-IDs, no zone / schedules / statistics */
  ot?: boolean;
  /** the ESP gas boiler hub over Modbus BMS (gb_ packages): the same OpenTherm-style cards, texts say Modbus BMS */
  gb?: boolean;
  /** the ESP MAGIS M hub (Midea M-Thermal, mt_ packages): the heat pump cards of the hub with its entities */
  mt?: boolean;
  /** the ESP OpenTherm hub (immergas_ot + ot_ packages): the OpenTherm cards with its entities; `source` stays
   *  "dominus" so the OpenTherm branches of the cards apply, texts and the extras check `esp` */
  esp?: boolean;
}

